import java.util.Optional;
public class Bonjour {
  static Optional<String> trouver(int id) {
    return id == 1 ? Optional.of("Web") : Optional.empty();
  }
  public static void main(String[] args) {
    System.out.println(trouver(1).orElse("Absent"));
    System.out.println(trouver(2).orElse("Absent"));
  }
}
